// Se carga antes del script principal. El control ocurre antes de abrir la aplicación.
async function uebraPasswordGate(user) {
 if (!navigator.onLine) {
  if(user.app_metadata?.uebra_must_change_password){document.querySelector('#loginmsg').textContent='Conéctese para cambiar su contraseña temporal.';return false}
  return true;
 }
 const result=await sb.functions.invoke('teacher-password',{body:{action:'status'}});
 if(result.error||result.data?.error){document.querySelector('#loginmsg').textContent='No se pudo verificar la contraseña. Revise la conexión y la función teacher-password de Supabase.';return false}
 if(!result.data.must_change_password)return true;
 document.querySelector('#app').classList.add('hide');
 document.querySelector('#login').classList.remove('hide');
 let old=document.querySelector('#passwordChange');if(old)old.remove();
 const form=document.createElement('form');form.id='passwordChange';form.className='card login';
 form.innerHTML='<h2>Cambiar contraseña temporal</h2><p>Antes de continuar, crea una contraseña personal de al menos 10 caracteres.</p><label class="field">Nueva contraseña<input id="newTeacherPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><label class="field">Confirmar contraseña<input id="confirmTeacherPassword" type="password" autocomplete="new-password" required></label><button class="primary wide">Guardar y continuar</button><p id="passwordChangeMessage" role="status"></p><button type="button" id="cancelPasswordChange">Cerrar sesión</button>';
 document.querySelector('#login .login').classList.add('hide');document.querySelector('#login').appendChild(form);
 form.querySelector('#cancelPasswordChange').onclick=async()=>{await sb.auth.signOut();location.reload()};
 form.onsubmit=async e=>{e.preventDefault();const password=form.querySelector('#newTeacherPassword').value,message=form.querySelector('#passwordChangeMessage');if(password!==form.querySelector('#confirmTeacherPassword').value){message.textContent='Las contraseñas no coinciden.';return}const button=form.querySelector('button');button.disabled=true;try{const r=await sb.functions.invoke('teacher-password',{body:{action:'change',password}});if(r.error||r.data?.error)throw Error(r.data?.error||r.error.message);await sb.auth.refreshSession();form.remove();document.querySelector('#login .login').classList.remove('hide');const u=await sb.auth.getUser();if(u.error)throw u.error;await boot(u.data.user)}catch(error){message.textContent='No se pudo cambiar: '+error.message}finally{button.disabled=false}};
 return false;
}

async function uebraResetTeacher(id,name,button){
 if(!confirm('¿Restablecer la contraseña de '+name+'? Deberá cambiar la clave temporal al ingresar.'))return;
 button.disabled=true;
 try{const r=await sb.functions.invoke('teacher-password',{body:{action:'reset',teacher_id:id}});if(r.error||r.data?.error)throw Error(r.data?.error||r.error.message);const box=document.createElement('div');box.className='notice';box.innerHTML='<b>Contraseña temporal para '+esc(name)+'</b><p>Entrégala al docente. Deberá cambiarla al ingresar.</p><input readonly class="obs"><button>Cerrar</button>';box.querySelector('input').value=r.data.temporary_password;box.querySelector('button').onclick=()=>box.remove();document.querySelector('#adminBody').prepend(box)}catch(e){toast('No se pudo restablecer: '+e.message,true)}finally{button.disabled=false}
}

const UEBRA_SAT_TYPES = [
 ['CLASES','Clases de refuerzo con docente'],
 ['DOCENTE','Tutorías personalizadas con docente'],
 ['ESPECIALISTA','Tutorías con especialista'],
 ['CASA','Estudios en casa con apoyo familiar']
];
function uebraSatQualitativeCourse(name){
 const text=String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
 return /PREPARATORIA|(?:PRIMERO|SEGUNDO|TERCERO|CUARTO)\s+EGB\b|^[1-4](?:[.°º]|\s)*(?:EGB|DE BASICA)\b/.test(text);
}
function uebraSatGrade(value,qualitative=false){
 if(value==null||String(value).trim()==='')return {low:false,label:'Pendiente',zero:false};
 if(qualitative){const label=uebraQualitativeGrade(value);return {low:['E-','E+','D-','D+','C-','C+'].includes(label),label,zero:false};}
 const n=Number(String(value).trim().replace(',','.'));
 return {low:Number.isFinite(n)&&n>=0.01&&n<=6.99,zero:n===0,label:Number.isFinite(n)?n.toFixed(2):'Sin equivalencia'};
}
function uebraSatCollect(students,detail,trimestre,qualitative){
 const items=new Map(detail.items.filter(i=>Number(i.trimestre)===Number(trimestre)).map(i=>[i.id,i]));
 const improvements=new Map(detail.improvements.map(i=>[i.student_grade_id,i]));
 const people=new Map(students.map(s=>[s.id,{student:s,evidence:[]}]));
 let zeros=0;
 for(const grade of detail.grades){
  const item=items.get(grade.grade_item_id),person=people.get(grade.student_id);if(!item||!person)continue;
  const raw=grade.nota,improvement=improvements.get(grade.id);
  const effective=/^[ABCDE][+-]$/.test(String(raw).trim())?raw:uebraExportInputResult(grade,improvement);
  const initial=uebraSatGrade(raw,qualitative),current=uebraSatGrade(effective,qualitative);
  if(current.zero){zeros++;continue}
  if(!current.low)continue;
  person.evidence.push({itemId:item.id,name:item.nombre,date:item.fecha||'',initial:initial.label,current:current.label,notes:grade.observacion||''});
 }
 return {rows:[...people.values()].filter(p=>p.evidence.length).sort((a,b)=>a.student.nombre.localeCompare(b.student.nombre)),zeros};
}
function uebraSatPlanDefaults(){return {types:[],learning:'',start:'',end:'',time:'',place:'',specialist:'',family:'',studentCommitment:'Realizar las actividades acordadas y participar en el refuerzo.',familyCommitment:'Acompañar al estudiante y mantener comunicación con el docente.',teacherCommitment:'Brindar acompañamiento, revisar las actividades y ofrecer retroalimentación.',notes:''};}
function uebraSatValidate(plan){
 if(!plan.types.length)return 'Seleccione al menos un tipo de refuerzo.';
 for(const [field,label] of [['learning','aprendizajes que necesitan apoyo'],['start','fecha de inicio'],['end','fecha de finalización'],['time','horario'],['place','lugar o medio de trabajo'],['studentCommitment','compromiso del estudiante'],['familyCommitment','compromiso de la familia'],['teacherCommitment','compromiso del docente']])if(!String(plan[field]||'').trim())return 'Complete '+label+'.';
 if(plan.end<plan.start)return 'La fecha de finalización debe ser igual o posterior al inicio.';

 if(plan.types.includes('ESPECIALISTA')&&!plan.specialist.trim())return 'Indique el especialista o escriba «Pendiente de coordinación».';
 return '';
}
async function uebraDownloadSat(a,trimestre,button){
 if(!teacher||!profile||!navigator.onLine){toast('Ingrese como docente y conéctese para consultar los insumos.',true);return}
 const owner=profile.id,tid=teacher.id;
 button.disabled=true;
 try{
  const [students,detail]=await Promise.all([
   uebraExportReadAll(()=>sb.from('students').select('id,nombre,cedula').eq('course_id',a.course_id).eq('estado','ACTIVO').order('id')),
   uebraLoadExportInputs(a)
  ]);
  if(profile?.id!==owner||teacher?.id!==tid){throw Error('La sesión cambió. Vuelva a ingresar.')}
  const qualitative=uebraSatQualitativeCourse(a.grado),result=uebraSatCollect(students,detail,trimestre,qualitative);
  if(!result.rows.length){toast('No hay insumos con alerta pendiente en este trimestre.'+(result.zeros?' Hay notas de 0,00 que requieren revisión docente.':''));return}
  uebraSatOpen({assignment:{...a},trimestre,qualitative,rows:result.rows,zeros:result.zeros,owner,teacherName:teacher.nombre||profile.nombre,date:ecuadorDate()});
 }catch(e){toast('No se pudo preparar el SAT: '+e.message,true)}finally{button.disabled=false}
}
function uebraSatLearning(row){return [...new Set(row.evidence.filter(e=>e.selected).map(e=>e.name))].join('; ')}
function uebraSatOpen(state,host=window){
 const document=host.document;
 const satBody=document.querySelector('#satBody');if(satBody)satBody.replaceChildren();
 document.querySelector('#satOverlay')?.remove();
 state.rows.forEach(r=>{r.selected=true;r.plan=uebraSatPlanDefaults();r.evidence.forEach(e=>e.selected=true);r.plan.learning=uebraSatLearning(r)});
 const overlay=document.createElement('div');overlay.id='satOverlay';overlay.style.cssText=satBody?'padding:0':host===window?'position:fixed;inset:0;background:#0007;z-index:2000;overflow:auto;padding:16px':'padding:16px';
 overlay.innerHTML=`<div class="card" style="max-width:980px;margin:0 auto"><div class="row"><div class="grow"><h2>Preparar Sistema de Alerta Temprana</h2><p>${esc(state.assignment.grado)} · ${esc(gradeSubjectLabel(state.assignment.asignatura))} · Trimestre ${state.trimestre}</p></div><button id="satClose">← Cursos y asignaturas</button></div><p class="notice">Revise los insumos detectados y complete el plan de cada estudiante antes de descargar. ${state.qualitative?'Criterio cualitativo: E− a C+.':'Criterio: 0,01 a 6,99/10 en insumos formativos.'} Se considera la nota actual con las mejoras registradas.</p>${state.zeros?`<p class="notice">${state.zeros} registro(s) con 0,00 requieren revisión: el rango numérico del acuerdo empieza en 0,01. No se convierten automáticamente en alertas.</p>`:''}<p class="muted">El plan se conserva mientras esta ventana permanezca abierta. Descargue los documentos antes de cerrar. El consolidado incluye el casillero de firma del representante de cada estudiante.</p><div class="row"><button id="satSelectAll">Seleccionar todos</button><button id="satSelectNone">Quitar selección</button><span id="satSelectionCount" class="muted" role="status" aria-live="polite"></span></div><div id="satPeople"></div><p id="satError" class="danger" role="alert"></p><div class="row"><button id="satConsolidated" class="primary">Descargar consolidado en Word</button></div></div>`;
 const root=overlay.querySelector('#satPeople');
 const fields=[['learning','Aprendizajes que necesitan mejora','textarea'],['start','Inicio','date'],['end','Finalización','date'],['time','Horario / frecuencia','text'],['place','Lugar o medio de trabajo','text'],['family','Nombre del representante (opcional)','text'],['studentCommitment','Compromiso del estudiante','textarea'],['familyCommitment','Compromiso de la familia','textarea'],['teacherCommitment','Compromiso del docente','textarea'],['notes','Observaciones (opcional)','textarea']];
 state.rows.forEach((row,index)=>{
  const card=document.createElement('details');card.className='card';card.open=false;
  card.innerHTML=`<summary><b>${esc(row.student.nombre)}</b> · ${row.evidence.length} insumo(s) con alerta <span data-sat-selected-label></span></summary><label style="display:block;margin:12px 0"><input type="checkbox" data-sat-person checked> Incluir a este estudiante</label><div class="tablewrap"><table class="report-table"><thead><tr><th>Incluir</th><th>Insumo</th><th>Fecha</th><th>Inicial</th><th>Actual</th></tr></thead><tbody>${row.evidence.map((e,i)=>`<tr><td><input type="checkbox" data-sat-evidence="${i}" aria-label="Incluir ${esc(e.name)}" checked></td><td>${esc(e.name)}</td><td>${esc(e.date)}</td><td>${esc(e.initial)}</td><td>${esc(e.current)}</td></tr>`).join('')}</tbody></table></div><fieldset style="margin:12px 0"><legend>Tipo de refuerzo (puede elegir varios)</legend>${UEBRA_SAT_TYPES.map(([key,label])=>`<label style="display:block;margin:8px 0"><input type="checkbox" data-sat-type="${key}"> ${label}</label>`).join('')}<label class="field" data-sat-specialist-wrap hidden>Especialista o estado de coordinación<input data-sat-field="specialist" placeholder="Nombre del profesional o Pendiente de coordinación"></label></fieldset><div class="report-filters">${fields.map(([key,label,type])=>`<label>${label}${type==='textarea'?`<textarea class="obs" data-sat-field="${key}" rows="2"></textarea>`:`<input type="${type}" data-sat-field="${key}">`}</label>`).join('')}</div><button type="button" data-sat-copy style="margin-top:12px">Aplicar este plan a los demás seleccionados</button>`;
  const selected=card.querySelector('[data-sat-person]');selected.onchange=()=>{row.selected=selected.checked;updateSelection()};
  card.querySelectorAll('[data-sat-evidence]').forEach(el=>el.onchange=()=>{row.evidence[Number(el.dataset.satEvidence)].selected=el.checked;row.plan.learning=uebraSatLearning(row);card.querySelector('[data-sat-field="learning"]').value=row.plan.learning;updateSelection()});
  card.querySelectorAll('[data-sat-field]').forEach(el=>{el.value=row.plan[el.dataset.satField];if(el.dataset.satField==='learning')el.readOnly=true;el.oninput=()=>row.plan[el.dataset.satField]=el.value});
  card.querySelectorAll('[data-sat-type]').forEach(el=>el.onchange=()=>{row.plan.types=Array.from(card.querySelectorAll('[data-sat-type]:checked'),e=>e.dataset.satType);card.querySelector('[data-sat-specialist-wrap]').hidden=!row.plan.types.includes('ESPECIALISTA')});
  card.querySelector('[data-sat-copy]').onclick=()=>{const error=uebraSatValidate(row.plan);if(error){toast(error,true);return}if(!confirm('¿Aplicar este plan a los demás estudiantes seleccionados? Se conservan sus nombres de representante.'))return;state.rows.forEach((other,j)=>{if(j===index||!other.selected)return;other.plan={...row.plan,types:[...row.plan.types],family:other.plan.family,learning:uebraSatLearning(other)};const otherCard=root.children[j];otherCard.querySelectorAll('[data-sat-field]').forEach(el=>el.value=other.plan[el.dataset.satField]);otherCard.querySelectorAll('[data-sat-type]').forEach(el=>el.checked=other.plan.types.includes(el.dataset.satType));otherCard.querySelector('[data-sat-specialist-wrap]').hidden=!other.plan.types.includes('ESPECIALISTA')});toast('Plan aplicado. Revise que se ajuste a cada estudiante.')};
  root.appendChild(card);
 });
 const general=document.createElement('section');general.id='satGeneral';general.className='card';
 general.innerHTML='<h3>Plan general de refuerzo</h3><p class="muted">Complete una sola vez el tipo de refuerzo y el cronograma comunes. Los aprendizajes se completan con los nombres de los insumos de cada estudiante. Aplíquelos a los estudiantes seleccionados; después puede abrir a un estudiante para ajustar su plan. Los campos vacíos conservan lo que ya tenga cada estudiante.</p>';
 general.appendChild(root.children[0].querySelector('fieldset').cloneNode(true));
 general.appendChild(root.children[0].querySelector('.report-filters').cloneNode(true));
 general.querySelector('[data-sat-field="family"]').closest('label').remove();
 general.querySelector('[data-sat-field="learning"]').closest('label').remove();
 general.querySelectorAll('[data-sat-type]').forEach(el=>{el.checked=false;el.onchange=()=>{general.querySelector('[data-sat-specialist-wrap]').hidden=!general.querySelector('[data-sat-type="ESPECIALISTA"]').checked}});
 const applyGeneral=document.createElement('button');applyGeneral.type='button';applyGeneral.className='primary';applyGeneral.style.marginTop='12px';applyGeneral.textContent='Aplicar plan general a los seleccionados';
 const generalStatus=document.createElement('p');generalStatus.className='muted';generalStatus.setAttribute('role','status');
 applyGeneral.onclick=()=>{
  const selected=state.rows.filter(r=>r.selected);if(!selected.length){generalStatus.textContent='Seleccione al menos un estudiante.';return}
  const changes={};general.querySelectorAll('[data-sat-field]').forEach(el=>{if(el.value.trim())changes[el.dataset.satField]=el.value});
  const types=Array.from(general.querySelectorAll('[data-sat-type]:checked'),el=>el.dataset.satType);if(types.length)changes.types=types;
  if(!Object.keys(changes).length){generalStatus.textContent='Complete algún campo del plan general.';return}
  if(selected.some(r=>r.plan.types.length||r.plan.start)&&!confirm('¿Actualizar los campos completados del plan de los estudiantes seleccionados? Los campos vacíos y los nombres de representante se conservan.'))return;
  selected.forEach(row=>{Object.assign(row.plan,changes);row.plan.types=[...row.plan.types];row.plan.learning=uebraSatLearning(row);const card=root.children[state.rows.indexOf(row)];card.querySelectorAll('[data-sat-field]').forEach(el=>el.value=row.plan[el.dataset.satField]);card.querySelectorAll('[data-sat-type]').forEach(el=>el.checked=row.plan.types.includes(el.dataset.satType));card.querySelector('[data-sat-specialist-wrap]').hidden=!row.plan.types.includes('ESPECIALISTA')});
  generalStatus.textContent='Plan general aplicado a '+selected.length+' estudiante(s). Puede descargar cuando estén completos los datos requeridos.';
 };
 general.appendChild(applyGeneral);general.appendChild(generalStatus);root.insertAdjacentElement('beforebegin',general);
 overlay.querySelector('#satClose').onclick=()=>{if(host.confirm('¿Cerrar la preparación del SAT? Los planes que no haya descargado se perderán.')){overlay.remove();if(satBody)uebraShowSat();else if(host!==window)host.close()}};
 function updateSelection(){
  const selected=state.rows.filter(r=>r.selected),inputs=selected.reduce((sum,r)=>sum+r.evidence.filter(e=>e.selected).length,0);
  overlay.querySelector('#satSelectionCount').textContent=selected.length+' de '+state.rows.length+' estudiantes · '+inputs+' insumos seleccionados';
  state.rows.forEach((row,i)=>root.children[i].querySelector('[data-sat-selected-label]').textContent=row.selected?'· Seleccionado':'· Sin seleccionar');
 }
 for(const [id,value] of [['satSelectAll',true],['satSelectNone',false]])overlay.querySelector('#'+id).onclick=()=>{state.rows.forEach((row,i)=>{row.selected=value;const card=root.children[i];card.querySelector('[data-sat-person]').checked=value;row.evidence.forEach(e=>e.selected=value);card.querySelectorAll('[data-sat-evidence]').forEach(el=>el.checked=value);row.plan.learning=uebraSatLearning(row);card.querySelector('[data-sat-field="learning"]').value=row.plan.learning});updateSelection()};
 updateSelection();
 async function output(kind,preview=false){
  const message=overlay.querySelector('#satError');message.textContent='';
  if(profile?.id!==state.owner){message.textContent='La sesión cambió. Vuelva a preparar el SAT.';return}
  const rows=state.rows.filter(r=>r.selected);
  if(!rows.length){message.textContent='Seleccione al menos un estudiante.';return}
  for(const row of rows){const error=!row.evidence.some(e=>e.selected)?'Seleccione al menos un insumo.':uebraSatValidate(row.plan);if(error){message.textContent=row.student.nombre+': '+error;root.children[state.rows.indexOf(row)].open=true;message.scrollIntoView({block:'nearest'});return}}
  let blob;try{blob=preview?new Blob([uebraSatDocument(state,rows,kind)],{type:'text/html;charset=utf-8'}):await uebraSatWord(state,rows,kind)}catch(error){message.textContent='No se pudo generar el Word: '+error.message;return}const url=URL.createObjectURL(blob);
  if(preview){const tab=host.open(url,'_blank');if(!tab){URL.revokeObjectURL(url);message.textContent='Permita abrir ventanas para ver las fichas o use Descargar fichas individuales.';return}setTimeout(()=>URL.revokeObjectURL(url),60000)}
  else{const link=document.createElement('a');link.href=url;link.download=('SAT_'+kind+'_'+state.assignment.grado+'_'+state.assignment.asignatura+'_T'+state.trimestre+'_'+state.date+'.docx').replace(/[\\/:*?"<>|]/g,'_');document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Word descargado. Abra el archivo .docx para editar o imprimir.')}
 }
 overlay.querySelector('#satConsolidated').onclick=()=>output('consolidado');
 (satBody||document.body).appendChild(overlay);
}
function uebraSatDocument(state,rows,kind){
 const a=state.assignment,text=value=>esc(String(value||'')).replace(/\r?\n/g,'<br>');
 const typeNames=plan=>UEBRA_SAT_TYPES.filter(([key])=>plan.types.includes(key)).map(([,label])=>label).join('; ');
 const head=title=>`<div class="letterhead" style="height:90px;overflow:hidden;margin-bottom:12px"><img style="display:block;width:100%" alt="Membrete institucional UEBRA" src="data:image/png;base64,${UEBRA_SAT_HEADER_IMAGE}"></div><div class="school">UNIDAD EDUCATIVA BENJAMÍN RAMÍREZ ARTEAGA</div><h1>${title}</h1><p>Año lectivo 2026–2027 · Sierra–Amazonía · Fecha de emisión: ${text(state.date)}<br>Curso: ${text(a.grado)} · Jornada: ${text(a.jornada)} · Trimestre: ${state.trimestre}<br>Asignatura: ${text(gradeSubjectLabel(a.asignatura))} · Docente: ${text(state.teacherName)}</p>`;
 const evidence=row=>row.evidence.filter(e=>e.selected);
 let content;
 if(kind==='consolidado')content=head('Notificación de alerta temprana y compromiso de refuerzo pedagógico')+`<p>Se comunica que, en los insumos formativos indicados, se han identificado aprendizajes que requieren apoyo. Se acuerda el siguiente plan de refuerzo y acompañamiento, con base en el artículo 10 del Acuerdo MINEDEC-MINEDEC-2026-00082-A y el artículo 32 del Reglamento General a la LOEI.</p><table><thead><tr><th>N.º</th><th>Estudiante</th><th>Insumos y notas actuales</th><th>Refuerzo</th><th>Cronograma</th><th>Firma del representante</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${text(r.student.nombre)}</b><br>${text(r.student.cedula)}</td><td>${evidence(r).map(e=>text(e.name)+' · '+text(e.current)+' · '+text(e.date)).join('<br>')}</td><td>${text(typeNames(r.plan))}${r.plan.specialist&&r.plan.types.includes('ESPECIALISTA')?'<br>Especialista: '+text(r.plan.specialist):''}</td><td>${text(r.plan.start)} a ${text(r.plan.end)}<br>Hora: ${text(r.plan.time)}<br>Lugar: ${text(r.plan.place)}</td><td style="min-width:100px;min-height:65px"></td></tr>`).join('')}</tbody></table>${uebraSatConsolidatedCommitments(rows,text)}<div class="signature">Firma del docente: ______________________________</div>`;
 else content=rows.map(row=>{
  const p=row.plan;
  return `<article>${head('Notificación de alerta temprana y compromiso de refuerzo pedagógico')}<p><b>Estudiante:</b> ${text(row.student.nombre)} · <b>Cédula:</b> ${text(row.student.cedula)}<br><b>Dirigido a:</b> ${text(p.family)||'Madre, padre, representante legal, adulto cuidador o estudiante autorrepresentado'}</p><p>Se comunica que, en los insumos formativos indicados, se han identificado aprendizajes que requieren apoyo. Se acuerda el siguiente plan de refuerzo y acompañamiento, con base en el artículo 10 del Acuerdo MINEDEC-MINEDEC-2026-00082-A y el artículo 32 del Reglamento General a la LOEI.</p><table><thead><tr><th>Insumo</th><th>Fecha</th><th>Nota inicial${state.qualitative?'':' /10'}</th><th>Nota actual${state.qualitative?'':' /10'}</th></tr></thead><tbody>${evidence(row).map(e=>`<tr><td>${text(e.name)}</td><td>${text(e.date)}</td><td>${text(e.initial)}</td><td>${text(e.current)}</td></tr>`).join('')}</tbody></table><h2>Plan de refuerzo pedagógico</h2><p><b>Tipo de refuerzo:</b> ${text(typeNames(p))}${p.types.includes('ESPECIALISTA')?'<br><b>Especialista o coordinación:</b> '+text(p.specialist):''}<br><b>Aprendizajes que necesitan mejora:</b> ${text(p.learning)}</p><p><b>Inicio:</b> ${text(p.start)} · <b>Finalización:</b> ${text(p.end)}<br><b>Horario o frecuencia:</b> ${text(p.time)} · <b>Lugar o medio:</b> ${text(p.place)}</p><h2>Compromisos de acompañamiento</h2><p><b>Estudiante:</b> ${text(p.studentCommitment)}<br><b>Familia:</b> ${text(p.familyCommitment)}<br><b>Docente:</b> ${text(p.teacherCommitment)}</p>${p.notes?'<p><b>Observaciones:</b> '+text(p.notes)+'</p>':''}<div class="signatures"><div>____________________________<br>Docente de la asignatura<br>${text(state.teacherName)}</div><div>____________________________<br>Representante / autorrepresentado<br>Nombre: ${text(p.family)||'____________________'}<br>Fecha: _____________________</div><div>____________________________<br>Estudiante</div><div>____________________________<br>Docente tutor / autoridad<br>Cuando corresponda</div></div><h2>Registro de seguimiento</h2><p>Resultado observado: ___________________________________________________<br>Próxima acción o ajuste: __________________________________________________<br>Fecha y responsable: ____________________________________________________</p></article>`;
 }).join('');
 return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SAT ${kind==='consolidado'?'Consolidado docente':'Fichas individuales'}</title><style>body{font-family:Arial,sans-serif;color:#111;max-width:${kind==='consolidado'?'1120':'780'}px;margin:24px auto;padding:0 12px;font-size:12px;line-height:1.45}.school{text-align:center;font-weight:bold;font-size:14px}h1{font-size:19px;text-align:center;margin:10px 0 16px}h2{font-size:14px;margin:15px 0 7px}p{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:12px 0}td,th{border:1px solid #aaa;padding:7px;overflow-wrap:anywhere;vertical-align:top}th{background:#eee}thead{display:table-header-group}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:35px 22px;margin-top:45px;break-inside:avoid}.signature{margin-top:45px}article+article{border-top:2px dashed #aaa;margin-top:35px;padding-top:25px}button{font:inherit;padding:10px;margin-bottom:18px;cursor:pointer}@media print{body{max-width:none;margin:0;padding:0}button{display:none}article+article{break-before:page;border:0;margin:0;padding:0}tr{break-inside:avoid}h2{break-after:avoid}}@page{size:A4 ${kind==='consolidado'?'landscape':'portrait'};margin:15mm}</style></head><body><button onclick="window.print()">Imprimir / guardar como PDF</button>${content}</body></html>`;
}

const UEBRA_SAT_WORD_TEMPLATE = "";
// Word real: conserva el paquete, membrete, imágenes y relaciones del modelo institucional.
async function uebraSatWord(state,rows,kind){
 if(!(await uebraEnsureExportLibrary('JSZip')))throw Error('No se pudo cargar la biblioteca de Word. Revise la conexión.');
 const zip=await JSZip.loadAsync(UEBRA_SAT_WORD_TEMPLATE,{base64:true});
 const parser=new DOMParser(),serializer=new XMLSerializer();
 const source=parser.parseFromString(await zip.file('word/document.xml').async('string'),'application/xml');
 const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';
 const body=source.getElementsByTagNameNS(ns,'body')[0];
 const section=body.getElementsByTagNameNS(ns,'sectPr')[0].cloneNode(true);
 const html=parser.parseFromString(uebraSatDocument(state,rows,kind),'text/html');
 // Firmas al final de la ficha, después del seguimiento.
 html.querySelectorAll('article').forEach(article=>{const signatures=article.querySelector('.signatures');if(signatures){const representative=signatures.children[1];if(representative)signatures.appendChild(representative);article.appendChild(signatures)}});
 const el=(tag,attrs={})=>{const e=source.createElementNS(ns,'w:'+tag);for(const [k,v] of Object.entries(attrs))e.setAttributeNS(ns,'w:'+k,String(v));return e};
 function contentText(node){if(node.nodeType===3)return node.textContent;if(node.nodeName==='BR')return '\n';return Array.from(node.childNodes).map(contentText).join('')}
 function paragraph(text,{bold=false,size=20,center=false,heading=false}={}){
  const p=el('p'),props=el('pPr');props.appendChild(el('spacing',{before:heading?120:0,after:90,line:240,lineRule:'auto'}));if(center)props.appendChild(el('jc',{val:'center'}));if(heading)props.appendChild(el('keepNext'));p.appendChild(props);
  const r=el('r'),rp=el('rPr');rp.appendChild(el('rFonts',{ascii:'Arial',hAnsi:'Arial',cs:'Arial'}));rp.appendChild(el('sz',{val:size}));rp.appendChild(el('color',{val:'000000'}));if(bold)rp.appendChild(el('b'));r.appendChild(rp);
  String(text).split('\n').forEach((line,i)=>{if(i)r.appendChild(el('br'));const t=el('t');t.setAttributeNS('http://www.w3.org/XML/1998/namespace','xml:space','preserve');t.textContent=line;r.appendChild(t)});p.appendChild(r);return p;
 }
 function table(node){
  const tbl=el('tbl'),props=el('tblPr');props.appendChild(el('tblW',{w:0,type:'auto'}));props.appendChild(el('tblLayout',{type:'fixed'}));const borders=el('tblBorders');for(const side of ['top','left','bottom','right','insideH','insideV'])borders.appendChild(el(side,{val:'single',sz:4,color:'D9D9D9'}));props.appendChild(borders);tbl.appendChild(props);
  const htmlRows=Array.from(node.rows),count=htmlRows[0].cells.length,total=10375,width=Math.floor(total/count),grid=el('tblGrid');for(let i=0;i<count;i++)grid.appendChild(el('gridCol',{w:width}));tbl.appendChild(grid);
  htmlRows.forEach(row=>{const tr=el('tr'),trPr=el('trPr');trPr.appendChild(el('cantSplit'));if(row.parentElement.tagName==='THEAD')trPr.appendChild(el('tblHeader'));tr.appendChild(trPr);Array.from(row.cells).forEach(cell=>{const tc=el('tc'),tcPr=el('tcPr');tcPr.appendChild(el('tcW',{w:width,type:'dxa'}));const margin=el('tcMar');for(const side of ['top','left','bottom','right'])margin.appendChild(el(side,{w:80,type:'dxa'}));tcPr.appendChild(margin);if(cell.tagName==='TH')tcPr.appendChild(el('shd',{fill:'EEEEEE'}));tc.appendChild(tcPr);tc.appendChild(paragraph(contentText(cell),{bold:cell.tagName==='TH',size:count>4?18:20}));tr.appendChild(tc)});tbl.appendChild(tr)});return tbl;
 }
 let articles=0;
 function convert(node){
  if(node.nodeType!==1)return;if(node.tagName==='BUTTON'||node.classList.contains('school')||node.classList.contains('letterhead'))return;
  if(node.tagName==='ARTICLE'){if(articles++){const p=el('p'),r=el('r');r.appendChild(el('br',{type:'page'}));p.appendChild(r);body.appendChild(p)}Array.from(node.children).forEach(convert);return}
  if(node.tagName==='TABLE'){body.appendChild(table(node));return}
  if(node.classList.contains('signatures')){Array.from(node.children).forEach(child=>{const p=paragraph(contentText(child));p.firstChild.appendChild(el('keepLines'));body.appendChild(p)});return}
  if(node.children.length&&node.tagName==='DIV'&&!node.classList.contains('signature')){Array.from(node.children).forEach(convert);return}
  body.appendChild(paragraph(contentText(node),{bold:/^H[12]$/.test(node.tagName),size:node.tagName==='H1'?24:node.tagName==='H2'?22:20,center:node.tagName==='H1',heading:/^H[12]$/.test(node.tagName)}));
 }
 while(body.firstChild)body.removeChild(body.firstChild);
 Array.from(html.body.children).forEach(convert);
 const margins=section.getElementsByTagNameNS(ns,'pgMar')[0];margins.setAttributeNS(ns,'w:top','1400');margins.setAttributeNS(ns,'w:bottom','650');
 body.appendChild(section);zip.file('word/document.xml',serializer.serializeToString(source));
 // Eliminar el año anterior del encabezado alternativo del modelo.
 if(zip.file('word/header2.xml'))zip.file('word/header2.xml',(await zip.file('word/header2.xml').async('string')).replaceAll('2025-2026','2026-2027'));
 return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',compression:'DEFLATE'});
}

const UEBRA_SAT_HEADER_IMAGE = "";

async function uebraShowSat(){
 const box=document.querySelector('#satBody');if(!box)return;
 if(!teacher){box.innerHTML='<div class="card"><h2>Sistema de Alerta Temprana</h2><p>La cuenta debe estar vinculada a un docente para preparar el SAT.</p></div>';return}
 box.innerHTML='<div class="card">Cargando cursos y asignaturas del SAT…</div>';
 try{
  const result=await sb.rpc('mis_asignaciones_calificaciones');if(result.error)throw result.error;
  const seen=new Set();const rows=(result.data||[]).filter(a=>{const key=gradeSubjectKey(a.asignatura),id=a.course_id+'|'+key;if(['OVP','TUTORIA','ANIMACION_LECTURA'].includes(key)||seen.has(id))return false;seen.add(id);return true});
  box.innerHTML='<div class="card"><h2>Sistema de Alerta Temprana (SAT)</h2><p class="muted">Seleccione curso, asignatura y trimestre para preparar el plan de refuerzo y descargar el Word con firmas.</p></div>'+(rows.length?'<div class="grade-grid">'+rows.map((a,i)=>`<div class="grade-card"><h3>${esc(gradeSubjectLabel(a.asignatura))}</h3><p>${esc(a.grado)} · ${esc(a.jornada)}</p><label class="field">Trimestre<select data-sat-term="${i}"><option value="1">1.º trimestre</option><option value="2">2.º trimestre</option><option value="3">3.º trimestre</option></select></label><button class="primary" data-sat-open="${i}">Preparar SAT</button></div>`).join('')+'</div>':'<div class="card">No hay asignaturas con insumos formativos asignadas a esta cuenta.</div>');
  box.querySelectorAll('[data-sat-open]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.satOpen);uebraDownloadSat(rows[i],Number(box.querySelector('[data-sat-term="'+i+'"]').value),button)});
 }catch(error){box.innerHTML='<div class="notice">No se pudo cargar el SAT: '+esc(error.message)+'</div>'}
}

function uebraSatConsolidatedCommitments(rows,text){
 const groups=new Map();for(const row of rows){const key=JSON.stringify([row.plan.studentCommitment,row.plan.familyCommitment,row.plan.teacherCommitment]);if(!groups.has(key))groups.set(key,{plan:row.plan,names:[]});groups.get(key).names.push(row.student.nombre)}
 return '<h2>Compromisos de acompañamiento</h2>'+[...groups.values()].map(g=>(groups.size>1?'<p><b>'+g.names.map(text).join('; ')+'</b></p>':'')+'<p><b>Estudiante:</b> '+text(g.plan.studentCommitment)+'<br><b>Familia:</b> '+text(g.plan.familyCommitment)+'<br><b>Docente:</b> '+text(g.plan.teacherCommitment)+'</p>').join('');
}
